// Pure helpers for the staging backend on Render (D4, D20): a test backend, not production. It runs the same
// patched copy as `npm run backend:local`, against the dev Neon database, with OTP test mode on.
import path from 'node:path';

import { buildBackendEnv, type Env, shouldCopy } from './env.ts';

export const STAGING = {
  name: 'apronhanger-staging-api',
  /** Folder in this repo that Render builds from (generated by `npm run staging:sync`). */
  rootDir: 'staging-backend',
  /** Same region as the Neon dev database (ap-southeast-1). */
  region: 'singapore',
};

const MIN_SECRET_LENGTH = 32;

/**
 * Environment variables for the Render service, from .env.local. Never production: `NODE_ENV=staging`, because OTP
 * test mode and the raised OTP limit switch themselves off when NODE_ENV is `production` (patches.ts).
 */
export function buildStagingEnv(local: Env, jwtSecret: string): Record<string, string> {
  if (jwtSecret.length < MIN_SECRET_LENGTH || jwtSecret === local.JWT_SECRET) {
    throw new Error(`Staging needs its own JWT secret of at least ${MIN_SECRET_LENGTH} characters.`);
  }
  // Validates the required keys, Neon-only databases (D13) and "not production".
  const { PORT: _port, BREVO_API_KEY: _email, ...base } = buildBackendEnv(local);
  const env: Record<string, string> = {
    ...base,
    NODE_ENV: 'staging',
    JWT_SECRET: jwtSecret,
    NODE_VERSION: '24.19.0',
    // Backend PR 7: Expo push on every new in-app notification, off unless this is true. Staging tests it on the phone.
    EXPO_PUSH_ENABLED: 'true',
  };
  return Object.fromEntries(Object.entries(env).filter(([, v]) => v !== ''));
}

export function buildRenderServicePayload(options: {
  ownerId: string;
  repo: string;
  env: Record<string, string>;
}) {
  return {
    type: 'web_service' as const,
    name: STAGING.name,
    ownerId: options.ownerId,
    repo: options.repo,
    branch: 'main',
    rootDir: STAGING.rootDir,
    autoDeploy: 'yes' as const,
    envVars: Object.entries(options.env).map(([key, value]) => ({ key, value })),
    serviceDetails: {
      runtime: 'node' as const,
      plan: 'free' as const,
      region: STAGING.region,
      healthCheckPath: '/health',
      envSpecificDetails: {
        buildCommand: 'npm ci && npm run build',
        // The job repo's migrations lag its schema (API.md note 17), so db push adds the missing tables.
        startCommand: 'npx prisma migrate deploy && npx prisma db push --skip-generate && node dist/index.js',
      },
    },
  };
}

/** What goes into staging-backend/: no installed packages, env files, tests or audit scripts. */
export function shouldCopyStaging(relPath: string): boolean {
  if (!shouldCopy(relPath)) return false;
  const first = relPath.split(/[\\/]/)[0];
  // logs/: what a local run of the backend or its tests wrote (may hold request data): never published.
  if (first === 'scripts' || first === 'app-scripts' || first === 'vitest.config.ts' || first === 'logs') return false;
  return !/(^|[\\/])__tests__([\\/]|$)/.test(relPath);
}

/**
 * Where `npm run staging:sync` copies the backend from: ../job/backend (read-only reference, the live code) by default,
 * or `--source <folder>` (relative to this repo), e.g. ../job-hotfix/backend with backend PR branches merged for staging.
 */
export function stagingSource(argv: string[], root: string): string {
  const i = argv.indexOf('--source');
  if (i === -1) return path.resolve(root, '..', 'job', 'backend');
  const value = argv[i + 1];
  if (!value || value.startsWith('--')) throw new Error('--source needs a folder');
  const source = path.resolve(root, value);
  const inside = path.relative(root, source);
  if (inside === '' || (!inside.startsWith('..') && !path.isAbsolute(inside))) {
    throw new Error(`--source must be outside this repo (${source})`);
  }
  return source;
}
